public List<TimeRange> buildTimeRanges(long start, long end) {


    final long maxRangeDuration = FETCH_DATA_DURATION;
    final long totalDuration = end - start;

    int numRanges = (int)Math.ceil((double)totalDuration / maxRangeDuration);
    long rangeStep = totalDuration / numRanges;

    List<TimeRange> ranges = new ArrayList<>();
    for (long i = 0; i < numRanges; i++) {
        long rangeStart = start + i * rangeStep;
        long rangeEnd = rangeStart + rangeStep - 1;
        if (i == numRanges - 1) {
            rangeEnd = end;
        }
        ranges.add(new TimeRange(rangeStart, rangeEnd));
    }
    return ranges;
}

